import { mkdir, readFile, rename, rm, stat, writeFile, chmod } from "node:fs/promises"
import { dirname, join } from "node:path"
import { homedir } from "node:os"

export interface MemoryNote {
  id: string
  text: string
  tags: string[]
  createdAt: string
  source: "manual" | "auto"
}

export interface PendingTurn {
  turnId: string
  messageID: string
  userExcerpt: string
  touchedFiles: string[]
  errors: string[]
  createdAt: string
}

export interface MemoryFile {
  version: 1
  sessionID: string
  parentSnapshotFrom: string | null
  summary: string
  notes: MemoryNote[]
  pendingTurns: PendingTurn[]
  needsConsolidation: boolean
  lastAttemptAt: string | null
  updatedAt: string
}

const SESSION_ID_RE = /^[A-Za-z0-9_-]+$/

export function sanitizeSessionID(sessionID: string): string {
  if (!SESSION_ID_RE.test(sessionID)) throw new Error(`Invalid sessionID: ${sessionID}`)
  return sessionID
}

export function dataRoot(): string {
  const xdg = process.env.XDG_DATA_HOME
  const base = xdg && xdg.trim() ? xdg : join(homedir(), ".local", "share")
  return join(base, "opencode")
}

export function memoryDir(): string {
  return join(dataRoot(), "memory-persistent", "sessions")
}

export function memoryPath(sessionID: string): string {
  const id = sanitizeSessionID(sessionID)
  return join(memoryDir(), `${id}.json`)
}

const locks = new Map<string, Promise<void>>()

async function withLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
  const prev = locks.get(key) ?? Promise.resolve()
  let resolve!: () => void
  const next = new Promise<void>((r) => {
    resolve = r
  })
  locks.set(key, prev.then(() => next))
  try {
    await prev
    return await fn()
  } finally {
    resolve()
    if (locks.get(key) === next) locks.delete(key)
  }
}

export function emptyMemory(sessionID: string, parentSnapshotFrom: string | null = null): MemoryFile {
  const now = new Date().toISOString()
  return {
    version: 1,
    sessionID,
    parentSnapshotFrom,
    summary: "",
    notes: [],
    pendingTurns: [],
    needsConsolidation: false,
    lastAttemptAt: null,
    updatedAt: now,
  }
}

export async function readMemory(sessionID: string): Promise<MemoryFile> {
  const id = sanitizeSessionID(sessionID)
  const path = memoryPath(id)
  try {
    const raw = await readFile(path, "utf8")
    const parsed = JSON.parse(raw) as MemoryFile
    if (parsed.version !== 1 || parsed.sessionID !== id) throw new Error("bad schema")
    return parsed
  } catch (err: any) {
    if (err?.code === "ENOENT") return emptyMemory(id)
    // corrupt recovery
    try {
      const backup = `${path}.corrupt.${Date.now()}`
      await rename(path, backup).catch(() => {})
    } catch {}
    return emptyMemory(id)
  }
}

export async function writeMemory(sessionID: string, memory: MemoryFile): Promise<void> {
  const id = sanitizeSessionID(sessionID)
  const path = memoryPath(id)
  memory.sessionID = id
  memory.updatedAt = new Date().toISOString()
  await mkdir(dirname(path), { recursive: true })
  await withLock(id, async () => {
    const tmp = `${path}.tmp.${process.pid}.${Date.now()}`
    await writeFile(tmp, JSON.stringify(memory, null, 2), { encoding: "utf8", mode: 0o600 })
    await rename(tmp, path)
    try {
      await chmod(path, 0o600)
    } catch {}
  })
}

export async function copyMemory(fromSessionID: string, toSessionID: string): Promise<void> {
  const from = await readMemory(fromSessionID)
  const copy = { ...from, sessionID: toSessionID, parentSnapshotFrom: fromSessionID, updatedAt: new Date().toISOString() }
  await writeMemory(toSessionID, copy)
}

export async function deleteMemoryFile(sessionID: string): Promise<void> {
  const path = memoryPath(sessionID)
  try {
    await rm(path, { force: true })
  } catch {}
}

export async function listMemoryFiles(): Promise<string[]> {
  const dir = memoryDir()
  try {
    const { readdir } = await import("node:fs/promises")
    const entries = await readdir(dir)
    return entries.filter((e) => e.endsWith(".json")).map((e) => e.replace(/\.json$/, ""))
  } catch {
    return []
  }
}

export function capPendingTurns(turns: PendingTurn[], max = 20): PendingTurn[] {
  if (turns.length <= max) return turns
  return turns.slice(turns.length - max)
}

export function sanitizeToolTarget(tool: string, input: unknown): string {
  if (!input || typeof input !== "object") return tool
  const obj = input as Record<string, unknown>
  const candidates = ["filePath", "path", "file", "target", "command", "name"]
  for (const key of candidates) {
    const val = obj[key]
    if (typeof val === "string" && val.trim()) {
      if (key === "command") {
        // store only first token (command name), never full command/output
        return `${tool}: ${val.trim().split(/\s+/)[0]}`
      }
      return `${tool}: ${val}`
    }
  }
  return tool
}

export function isSignificantTool(tool: string): boolean {
  const significant = new Set(["write", "edit", "patch", "bash", "shell", "apply_patch", "multiedit"])
  return significant.has(tool.toLowerCase())
}

