// Refined: strip command substitutions first, then strip assignments, then take first token.
const ALLOW = new Set(["git","bun","npm","pnpm","yarn","node","deno","make","cmake","cargo","go","gradle","mvn","tsc","jest","vitest","pytest","ruff","mypy","eslint","prettier","black","pip","pip3","poetry","uv","docker","docker-compose","kubectl","terraform","psql","mysql","curl","wget","ssh","scp","rsync","rm","mv","cp","mkdir","touch","chmod","systemctl","brew","apt","gcc","clang","python","python3"])

export function segCommands(command: string): string[] {
  const stripped = command
    .replace(/`[^`]*`/g, " ")          // backtick substitution
    .replace(/\$\([^)]*\)/g, " ")       // $( ... ) substitution
    .replace(/\$\{[^}]*\}/g, " ")       // ${ ... } expansion
  const out: string[] = []
  for (const raw of stripped.split(/&&|\|\||;|\n|\|/)) {
    const toks = raw.trim().split(/\s+/).filter(Boolean)
    let i = 0
    while (i < toks.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(toks[i])) i++
    if (i < toks.length) out.push(toks[i])
  }
  return out
}
export function classify(command: string) {
  const kept: string[] = [], dropped: string[] = []
  for (const c of segCommands(command)) (ALLOW.has(c) ? kept : dropped).push(c)
  return { kept, dropped }
}
