function count(s: string) { return s.length }
type Section = { name: string; text: string; capPct: number }
const order = ["summary", "conversation", "notes", "activity"]

function injectV1(sections: Section[], B: number) {           // DESIGN AS WRITTEN
  const byName = Object.fromEntries(sections.map(s => [s.name, s]))
  let used = 0; const out: string[] = []
  for (const name of order) {
    const s = byName[name]; if (!s?.text) continue
    const cap = Math.min(Math.floor(B * s.capPct), B - used)
    if (cap <= 0) continue
    const piece = s.text.slice(0, cap)
    if (piece) { out.push(piece); used += count(piece) }
  }
  return { text: out.join("\n\n"), used, waste: B - used }
}

function injectV2(sections: Section[], B: number) {           // FIXED: redistribute leftover
  const byName = Object.fromEntries(sections.map(s => [s.name, s]))
  const natural = order.map(n => byName[n]?.text ?? "")
  const allowance = order.map((n, i) => Math.min(count(natural[i]), Math.floor(B * byName[n].capPct)))
  let sum = allowance.reduce((a, b) => a + b, 0)
  if (sum > B) {                                              // scale down proportionally
    const k = B / sum
    for (let i = 0; i < allowance.length; i++) allowance[i] = Math.floor(allowance[i] * k)
    sum = allowance.reduce((a, b) => a + b, 0)
  } else {
    let leftover = B - sum                                   // give back to truncated sections
    for (let i = 0; i < allowance.length && leftover > 0; i++) {
      const room = count(natural[i]) - allowance[i]
      if (room > 0) { const give = Math.min(room, leftover); allowance[i] += give; leftover -= give }
    }
  }
  let used = 0; const out: string[] = []
  order.forEach((n, i) => {
    if (!natural[i]) return
    const piece = natural[i].slice(0, allowance[i])
    if (piece) { out.push(piece); used += count(piece) }
  })
  return { text: out.join("\n\n"), used, waste: B - used }
}

